from typing import List, Tuple

class UnionFind:
    def __init__(self):
        self.parent = {}

    def find(self, node):
        if node not in self.parent:
            self.parent[node] = node
            return node
        elif self.parent[node]!= node:
            parent = self.parent[node]
            self.parent[node] = self.find(parent)
            return self.parent[node]
        else:
            return node

    def join(self, a: int, b: int) -> int:
        parent_a, parent_b = self.find(a), self.find(b)
        if parent_a == parent_b:
            return 0
        self.parent[parent_a] = parent_b
        return 1   

def f(N: int, M: int, edges: List[Tuple[int, int,  int]]) -> float:
    u = UnionFind()
    res = 0.0
    for e, w in edges:
        x, y, z = e, u.find(y), w        
        weight, size = z, u.join(x, y) + 1
        res += size * weight - (size - 1) * weight // 2
    world_ran = N*(N-1) // 2 
    for i in range(N):
        res += (N - u.find(i)) * N
    return (1000000000 * world_ran - res) / world_ran

